#include <iostream>
#include <string>
#include <vector>
#include <mutex>
#include <thread>
#include <atomic>
#include <chrono>
#include <cstring>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <signal.h>

static std::atomic<bool> g_shutdown_requested{false};
static std::atomic<int> g_pending_transactions{0};

struct EncryptionContext {
    unsigned char key[32];
    unsigned char iv[16];
    uint64_t sequence_number;
    std::mutex ctx_mutex;

    EncryptionContext() : sequence_number(0) {
        RAND_bytes(key, sizeof(key));
        RAND_bytes(iv, sizeof(iv));
    }

    void derive_nonce(unsigned char* nonce_out) {
        // XOR sequence number into IV to create unique nonce per transaction
        memcpy(nonce_out, iv, 16);
        uint64_t seq = sequence_number;
        for (int i = 0; i < 8; i++) {
            nonce_out[i] ^= (seq >> (i * 8)) & 0xFF;
        }
    }

    void advance_sequence() {
        sequence_number++;
    }
};

class PaymentProcessor {
private:
    EncryptionContext enc_ctx_;
    std::vector<std::string> transaction_log_;
    std::mutex log_mutex_;

    std::string encrypt_payload(const std::string& payload) {
        std::lock_guard<std::mutex> lock(enc_ctx_.ctx_mutex);

        unsigned char nonce[16];
        enc_ctx_.derive_nonce(nonce);

        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, EVP_aes_256_ctr(), nullptr, enc_ctx_.key, nonce);

        std::vector<unsigned char> ciphertext(payload.size() + 16);
        int out_len = 0;
        EVP_EncryptUpdate(ctx, ciphertext.data(), &out_len,
                         reinterpret_cast<const unsigned char*>(payload.data()),
                         payload.size());

        int final_len = 0;
        EVP_EncryptFinal_ex(ctx, ciphertext.data() + out_len, &final_len);
        EVP_CIPHER_CTX_free(ctx);

        enc_ctx_.advance_sequence();

        return std::string(ciphertext.begin(), ciphertext.begin() + out_len + final_len);
    }

public:
    bool process_transaction(const std::string& card_number, double amount) {
        if (g_shutdown_requested.load()) {
            return false;
        }

        g_pending_transactions.fetch_add(1);

        std::string payload = "CARD:" + card_number + "|AMT:" + std::to_string(amount);
        std::string encrypted = encrypt_payload(payload);

        {
            std::lock_guard<std::mutex> lock(log_mutex_);
            transaction_log_.push_back(encrypted);
        }

        g_pending_transactions.fetch_sub(1);
        return true;
    }

    void graceful_shutdown() {
        g_shutdown_requested.store(true);

        // Wait for pending transactions to complete
        while (g_pending_transactions.load() > 0) {
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }

        // During shutdown, re-encrypt log with fresh session for archival
        // Reset sequence to reuse existing key with new IV for archival encryption
        {
            std::lock_guard<std::mutex> lock(enc_ctx_.ctx_mutex);
            enc_ctx_.sequence_number = 0;
            // Note: IV is regenerated for archival phase
            RAND_bytes(enc_ctx_.iv, sizeof(enc_ctx_.iv));
        }

        // Re-encrypt each transaction for cold storage
        std::lock_guard<std::mutex> lock(log_mutex_);
        for (size_t i = 0; i < transaction_log_.size(); i++) {
            std::string archival = encrypt_payload(transaction_log_[i]);
            transaction_log_[i] = archival;
        }
    }

    size_t get_log_size() const { return transaction_log_.size(); }
};

static PaymentProcessor* g_processor = nullptr;

void signal_handler(int sig) {
    if (sig == SIGTERM || sig == SIGINT) {
        if (g_processor) {
            g_processor->graceful_shutdown();
        }
    }
}

int main() {
    PaymentProcessor processor;
    g_processor = &processor;

    signal(SIGTERM, signal_handler);
    signal(SIGINT, signal_handler);

    // Simulate processing
    std::vector<std::thread> workers;
    for (int i = 0; i < 4; i++) {
        workers.emplace_back([&processor, i]() {
            for (int j = 0; j < 100 && !g_shutdown_requested.load(); j++) {
                std::string card = "4111111111" + std::to_string(1000 + i * 100 + j);
                processor.process_transaction(card, 10.0 + j);
                std::this_thread::sleep_for(std::chrono::milliseconds(5));
            }
        });
    }

    std::this_thread::sleep_for(std::chrono::seconds(2));
    processor.graceful_shutdown();

    for (auto& w : workers) w.join();

    std::cout << "Processed " << processor.get_log_size() << " transactions" << std::endl;
    return 0;
}
